const crypto = require('crypto');

const MS_PER_SECOND = 1000;
const REPLAY_WINDOW_SECONDS = 300;
const secret = $env.N8N_WEBHOOK_SECRET;

if (!secret) {
  throw new Error('N8N_WEBHOOK_SECRET is not set');
}

const { headers = {}, body } = $input.first().json;
const payload = body?.payload;
const timestamp = headers['x-lendloop-timestamp'];
const signature = String(headers['x-lendloop-signature'] || '').replace(/^sha256=/, '');
const nowSeconds = Math.floor(Date.now() / MS_PER_SECOND);
const ageSeconds = Math.abs(nowSeconds - Number(timestamp));

function isAuthentic() {
  if (typeof payload !== 'string' || !timestamp || !signature) return false;

  if (!Number.isFinite(ageSeconds) || ageSeconds > REPLAY_WINDOW_SECONDS) return false;

  const expected = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${payload}`)
    .digest('hex');

  return (
    expected.length === signature.length &&
    crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature))
  );
}

if (!isAuthentic()) {
  return [{ json: { valid: false } }];
}

const event = JSON.parse(payload);
const delivered = $getWorkflowStaticData('global').deliveredEventIds || {};

return [{ json: { valid: true, duplicate: Boolean(delivered[event.eventId]), event } }];

const DEDUPE_WINDOW_MS = 24 * 60 * 60 * 1000;
const { event } = $input.first().json;

const notification = {
  recipient: event.recipientName,
  message: `[LendLoop] ${event.toolName} (${event.startDate} to ${event.endDate}) is now: ${event.status}`,
  eventId: event.eventId,
  dispatchedAt: new Date().toISOString(),
};

console.log('[LendLoop Notification]', JSON.stringify(notification));

const store = $getWorkflowStaticData('global');
const delivered = store.deliveredEventIds || {};
const cutoff = Date.now() - DEDUPE_WINDOW_MS;

for (const [eventId, deliveredAt] of Object.entries(delivered)) {
  if (deliveredAt < cutoff) delete delivered[eventId];
}

delivered[event.eventId] = Date.now();
store.deliveredEventIds = delivered;

return [{ json: notification }];
